scripts.host.probe:
{
  "schema": 1,
  "timeout_ms": 180000,
  "steps": [
    {
      "op": "wait",
      "scope": "menu",
      "screen": "MultiplayerScreen",
      "control": "LabelMultiplayerStatus",
      "text_contains": "Waiting for Joiner to press Ready"
    },
    {
      "op": "wait",
      "elapsed_ms": 18000,
      "scope": "menu"
    },
    {
      "op": "assert_relay",
      "scope": "menu"
    },
    {
      "op": "menu",
      "command": "video_mark countdown-relay-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "countdown-relay-host",
      "scope": "menu"
    },
    {
      "op": "signal",
      "name": "done",
      "scope": "menu"
    },
    {
      "op": "finish"
    }
  ]
}

scripts.joiner.probe:
{
