      "text_contains": "Press Ready when you're ready to play"
    },
    {
      "op": "wait",
      "elapsed_ms": 18000,
      "scope": "menu"
    },
    {
      "op": "assert_relay",
      "scope": "menu"
    },
    {
      "op": "menu",
      "command": "video_mark countdown-relay-joiner"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "countdown-relay-joiner",
      "scope": "menu"
    },
    {
      "op": "signal",
      "name": "done",
      "scope": "menu"
    },
    {
      "op": "finish"
    }
  ]
}
